SCHOOLS_DB = json.loads(SCHOOLS_JSON)

# Γενικές λέξεις που αγνοούνται όταν συγκρίνουμε ονόματα σχολείων
GENERIC_WORDS = {
    "σχολειο", "σχολειου", "σχολειων", "δημοτικο", "δημοτικου", "δημ",
    "δ.σ", "δσ", "νηπιαγωγειο", "νηπιαγωγειου", "νηπ", "ν/γ", "νγ",
    "ολοημερο", "ολοημερου", "ειδικο", "ειδικης", "αγωγης", "πρωτυπο",
    "πειραματικο", "τμημα", "ενταξης", "της", "του", "και",
}


def strip_accents(text):
    """Αφαιρεί τόνους (π.χ. 'ά'->'α') κρατώντας το ελληνικό αλφάβητο."""
    return "".join(c for c in unicodedata.normalize("NFD", text) if unicodedata.category(c) != "Mn")


def norm(text):
    """Πεζά + χωρίς τόνους + χωρίς διπλά κενά, για ασφαλείς συγκρίσεις κειμένου."""
    return re.sub(r"\s+", " ", strip_accents(text).strip()).lower()


def extract_number_anywhere(text):
    """Βρίσκει τον αριθμό σχολείου οπουδήποτε μέσα στο κείμενο (π.χ. και στο
    'ΔΗΜ. ΣΧΟΛΕΙΟ ΑΘΗΝΩΝ 32ο' και στο '32ο Δημοτικό Σχολείο Αθηνών')."""
    m = re.search(r"(?:^|\s)(\d+)\s*[οΟoO](?:\b|\s|$)", text)
    return m.group(1) if m else None


# Προ-υπολογισμός για κάθε εγγραφή: αριθμός (από το alt_name, που πάντα
# ξεκινάει με αριθμό) + normalized εκδοχές ΚΑΙ των δύο ονομάτων (name/alt_name)
for _entry in SCHOOLS_DB:
    _entry["_number"] = extract_number_anywhere(_entry.get("alt_name", _entry["name"]))
    _entry["_norm_name"] = norm(_entry["name"])
    _entry["_norm_alt"] = norm(_entry.get("alt_name", _entry["name"]))


def find_in_database(name):
    """Ψάχνει το σχολείο μέσα στην ενσωματωμένη επίσημη βάση.
    Συγκρίνει το κείμενο που έδωσε ο χρήστης ΚΑΙ με το πρωτότυπο όνομα (name)
    ΚΑΙ με την αναδιατυπωμένη μορφή (alt_name), κρατώντας το καλύτερο σκορ -
    ώστε να αναγνωρίζονται και οι δύο μορφές γραφής.
    Επιστρέφει (entry, score) ή (None, 0)."""
    number = extract_number_anywhere(name)
    target = norm(name)

    candidates = SCHOOLS_DB
    if number:
        same_number = [e for e in SCHOOLS_DB if e["_number"] == number]
        if same_number:
            candidates = same_number

    best, best_score = None, 0.0
    for entry in candidates:
        score_name = difflib.SequenceMatcher(None, target, entry["_norm_name"]).ratio()
        score_alt = difflib.SequenceMatcher(None, target, entry["_norm_alt"]).ratio()
        score = max(score_name, score_alt)
        if score > best_score:
            best_score, best = score, entry
    return best, best_score


def geocode_photon(address, tries=2):
    """Εναλλακτικός geocoder (Komoot Photon, βασισμένος σε OSM δεδομένα, χωρίς κλειδί).
    Δεν ανήκει στο OpenStreetMap Foundation, οπότε δεν επηρεάζεται από τα μπλοκ IP
    που εφαρμόζει το nominatim.openstreetmap.org σε πολλά cloud hosting (π.χ. Streamlit Cloud)."""
    errors = []
    for _ in range(tries):
        try:
            r = requests.get(
                "https://photon.komoot.io/api/",
                params={"q": address, "limit": 1, "lang": "en"},
                headers={"User-Agent": "teacher-closest-school-finder-webapp"},
                timeout=10,
            )
            r.raise_for_status()
            feats = r.json().get("features", [])
            if feats:
                lon, lat = feats[0]["geometry"]["coordinates"]
                return (lat, lon), errors
            errors.append("Photon: καμία αντιστοίχιση")
            break
        except Exception as e:
            errors.append(f"Photon: {e}")
            time.sleep(1)
    return None, errors


def geocode_nominatim(addr, tries=3):
    errors = []
    for _ in range(tries):
        try:
            loc = geolocator.geocode(addr, timeout=10)
            if loc:
                return (loc.latitude, loc.longitude), errors
            errors.append("Nominatim: καμία αντιστοίχιση")
            break
        except Exception as e:
            errors.append(f"Nominatim: {e}")
            time.sleep(1)
    return None, errors


def geocode_address(address, tries=3):
    """Δοκιμάζει πρώτα Photon και μετά Nominatim. Επιστρέφει (coords, debug_errors)."""
    addr = address.strip()
    if not re.search(r"ελλ[αά]δα|greece", addr, re.IGNORECASE):
        addr = addr + ", Ελλάδα"

    coords, err1 = geocode_photon(addr, tries=2)
    if coords:
        return coords, []

    coords, err2 = geocode_nominatim(addr, tries=tries)
    if coords:
        return coords, []

    return None, err1 + err2


def clean_school_name(raw_line):
    line = raw_line.strip()
    line = re.sub(r"\(.*?\)", "", line)
    line = re.sub(r"^\d+[\.\)]\s*", "", line)
    line = re.sub(r"\s{2,}", " ", line).strip()
    return line


def looks_like_school_line(line):
    keywords = [
        "ΔΗΜ", "ΝΗΠ", "ΣΧΟΛΕΙ", "Δ.Σ", "Ν/Γ",
        "ΟΛΟΗΜΕΡ", "ΕΙΔΙΚΟ", "ΕΛΕΠΑΠ",
    ]
    upper = line.upper()
    return any(k in upper for k in keywords)


@st.cache_data(show_spinner=False, ttl=60 * 60 * 24)
def query_overpass(name):
    """Εφεδρική αναζήτηση στο OpenStreetMap, μόνο για σχολεία που ΔΕΝ βρέθηκαν
    στην ενσωματωμένη επίσημη βάση (π.χ. σχολεία άλλης Διεύθυνσης)."""
    s, w, n, e = ATTICA_BBOX
    number = extract_number_anywhere(name)
    if number:
        name_regex = rf"^\s*{number}\s*[οΟoO]"
    else:
        name_regex = re.escape(name)
    query = f"""
    [out:json][timeout:25];
    (
      node["amenity"~"school|kindergarten"]["name"~"{name_regex}",i]({s},{w},{n},{e});
      way["amenity"~"school|kindergarten"]["name"~"{name_regex}",i]({s},{w},{n},{e});
      relation["amenity"~"school|kindergarten"]["name"~"{name_regex}",i]({s},{w},{n},{e});
    );
    out center tags;
    """
    try:
        r = requests.post(OVERPASS_URL, data={"data": query}, timeout=30)
        r.raise_for_status()
        return r.json().get("elements", [])
    except Exception:
        return []


def best_osm_match(name, elements):
    target = norm(name)
    best, best_score = None, 0.0
    for el in elements:
        cand_name = el.get("tags", {}).get("name", "")
        score = difflib.SequenceMatcher(None, target, norm(cand_name)).ratio()
        if score > best_score:
            best_score, best = score, el
    return best, best_score


def get_osm_coords(el):
    if "lat" in el and "lon" in el:
        return el["lat"], el["lon"]
    center = el.get("center")
    if center:
        return center["lat"], center["lon"]
    return None


def _in_attica(lat, lon):
    """Ελέγχει ότι ένα σημείο βρίσκεται όντως μέσα στην ευρύτερη Αττική.
    Χρησιμοποιείται σαν δικλείδα ασφαλείας: αν το geocoding επιστρέψει κάτι
    εκτός αυτού του πλαισίου, κάτι πήγε στραβά και το απορρίπτουμε."""
    s, w, n, e = ATTICA_BBOX
    return s <= lat <= n and w <= lon <= e


def build_address_candidates(entry):
    """Φτιάχνει μια λίστα εναλλακτικών διευθύνσεων προς δοκιμή, από την πιο
    ακριβή στην πιο γενική - χρήσιμο όταν η πλήρης διεύθυνση (π.χ. με 'ΟΔΟΣ
    & ΟΔΟΣ' σε γωνία δύο δρόμων) μπερδεύει τον geocoder."""
    street = entry.get("street", "").strip()
    postcode = entry.get("postcode", "").strip()
    area = entry.get("area", "").strip()
    postcode_part = f"{postcode} " if postcode else ""

    candidates = []
    if street:
        candidates.append(f"{street}, {postcode_part}{area}, Ελλάδα")
        # Αν είναι γωνία δύο δρόμων ("Χ & Ψ"), δοκίμασε μόνο τον πρώτο δρόμο
        if "&" in street:
            first_street = street.split("&")[0].strip()
            if first_street:
                candidates.append(f"{first_street}, {postcode_part}{area}, Ελλάδα")
        # Χωρίς Τ.Κ.
        if postcode:
            candidates.append(f"{street}, {area}, Ελλάδα")
    # Μόνο Τ.Κ. + περιοχή (πιο γενικό, αλλά πάντα μέσα στη σωστή γειτονιά)
    if postcode:
        candidates.append(f"{postcode} {area}, Ελλάδα")
    if area:
        candidates.append(f"{area}, Ελλάδα")
    return candidates


def geocode_db_entry(entry):
    """Δοκιμάζει διαδοχικά τις εναλλακτικές διευθύνσεις μέχρι να πετύχει μία
    μέσα στα όρια της Αττικής. Επιστρέφει (coords, address_used) ή (None, None)."""
    for addr in build_address_candidates(entry):
        coords, _ = geocode_address(addr)
        if coords and _in_attica(*coords):
            return coords, addr
    return None, None


@st.cache_data(show_spinner=False, ttl=60 * 60 * 24)
def locate_school(name):
    """Επιστρέφει (lat, lon, address, method, matched_name) ή None.
    Σειρά προτεραιότητας:
    1) Ενσωματωμένη επίσημη βάση Α' Αθήνας (πιο αξιόπιστο - πραγματική διεύθυνση)
    2) OpenStreetMap (αναζήτηση με βάση το όνομα, εφεδρικά)
    3) Photon / Nominatim (αναζήτηση με βάση το όνομα ως τοποθεσία, έσχατη λύση)
    """
    # 1) Επίσημη βάση
    entry, score = find_in_database(name)
    if entry and score > 0.40:
        coords, addr_used = geocode_db_entry(entry)
        if coords:
            postcode_part = f"{entry['postcode']} " if entry.get("postcode") else ""
            display_address = f"{entry['street']}, {postcode_part}{entry['area']}".strip()
            return coords[0], coords[1], display_address, "Επίσημη λίστα (Α'/Β'/Δ' Αθήνας)", entry["name"]

    # 2) OpenStreetMap POI αναζήτηση (π.χ. σχολεία εκτός Α' Αθήνας)
    elements = query_overpass(name)
    if elements:
        el, osm_score = best_osm_match(name, elements)
        if el and osm_score > 0.30:
            coords = get_osm_coords(el)
            if coords:
                tags = el.get("tags", {})
                addr_parts = [tags.get("addr:street", ""), tags.get("addr:housenumber", ""), tags.get("addr:city", "")]
                address = " ".join(p for p in addr_parts if p).strip()
                if not address:
                    address = "Διεύθυνση μη διαθέσιμη στο OpenStreetMap"
                matched_name = tags.get("name", name)
                return coords[0], coords[1], address, "OpenStreetMap (κατά προσέγγιση)", matched_name

    # 3) Έσχατη λύση: αναζήτηση ονόματος ως τοποθεσία
    for attempt_query in (f"{name}, Αθήνα, Ελλάδα", f"{name}, Αττική, Ελλάδα"):
        coords, _ = geocode_photon(attempt_query, tries=1)
        if coords and _in_attica(*coords):
            return coords[0], coords[1], "Άγνωστη ακριβής διεύθυνση (κατά προσέγγιση)", "Photon (κατά προσέγγιση)", name
        try:
            loc = geolocator.geocode(attempt_query, timeout=10)
            if loc and _in_attica(loc.latitude, loc.longitude):
                return loc.latitude, loc.longitude, loc.address, "Nominatim (κατά προσέγγιση)", name
        except Exception:
            time.sleep(1)
    return None


# =======================================================================
# UI
# =======================================================================
st.set_page_config(page_title="Πλησιέστερο Σχολείο", page_icon="🏫", layout="wide")
st.title("🏫 Εύρεση πλησιέστερου σχολείου")
st.caption(f"Πρωτοβάθμια Εκπαίδευση (Δημοτικά & Νηπιαγωγεία) - Α', Β' & Δ' Αθήνας · {len(SCHOOLS_DB)} μονάδες στην ενσωματωμένη βάση")

col1, col2 = st.columns([1, 1])

with col1:
    home_address = st.text_input(
        "Διεύθυνση κατοικίας σου",
        placeholder="π.χ. Πατησίων 100, Αθήνα",
    )

with col2:
    schools_raw = st.text_area(
        "Λίστα σχολείων (ένα σχολείο ανά γραμμή)",
        height=150,
        placeholder="32ο σχολείο Αθηνών\n2ο σχολείο Καισαριανής\n5ο σχολείο Νέας Φιλαδέλφειας",
    )

run = st.button("🔎 Βρες αποστάσεις & χάρτη", type="primary")

if run:
    if not home_address.strip():
        st.error("Συμπλήρωσε πρώτα τη διεύθυνση κατοικίας σου.")
        st.stop()
    if not schools_raw.strip():
        st.error("Επικόλλησε τη λίστα σχολείων.")
        st.stop()

    with st.spinner("Εντοπισμός διεύθυνσης κατοικίας..."):
        home_coords, geocode_errors = geocode_address(home_address)

    if not home_coords:
        st.error(
            "Δεν μπόρεσα να εντοπίσω αυτή τη διεύθυνση. Δοκίμασε πιο συγκεκριμένη μορφή "
            "(οδός, αριθμός, περιοχή)."
        )
        if geocode_errors:
            with st.expander("Τεχνικές λεπτομέρειες (για αν χρειαστεί υποστήριξη)"):
                for e in geocode_errors:
                    st.code(e)
        st.stop()

    st.success(f"Το σπίτι εντοπίστηκε στις συντεταγμένες: {home_coords}")

    raw_lines = [l for l in schools_raw.splitlines() if l.strip()]
    school_names = []
    for line in raw_lines:
        cleaned = clean_school_name(line)
        if cleaned and looks_like_school_line(cleaned):
            school_names.append(cleaned)
    school_names = list(dict.fromkeys(school_names))

    if not school_names:
        st.warning("Δεν αναγνωρίστηκε κανένα όνομα σχολείου στη λίστα.")
        st.stop()

    st.write(f"Βρέθηκαν **{len(school_names)}** πιθανά σχολεία. Αναζήτηση σε εξέλιξη...")
    progress = st.progress(0.0)
    status = st.empty()

    # ΣΗΜΑΝΤΙΚΟ: μόνο τα σχολεία που έγραψες παρακάτω θα εμφανιστούν στον χάρτη.
    results = []
    not_found = []
    for i, name in enumerate(school_names):
        status.write(f"Αναζήτηση: {name}")
        found = locate_school(name)
        if found:
            lat, lon, address, method, matched_name = found
            dist_km = geodesic(home_coords, (lat, lon)).km
            results.append({
                "Έγραψες": name,
                "Βρέθηκε ως": matched_name,
                "Απόσταση (χλμ)": round(dist_km, 2),
                "Διεύθυνση": address, "Πηγή": method,
                "_lat": lat, "_lon": lon,
            })
        else:
            not_found.append(name)
        progress.progress((i + 1) / len(school_names))
        time.sleep(0.2)

    status.empty()
    progress.empty()
    results.sort(key=lambda r: r["Απόσταση (χλμ)"])

    st.subheader("Αποτελέσματα (ταξινομημένα κατά απόσταση)")
    st.dataframe(
        [{k: v for k, v in r.items() if not k.startswith("_")} for r in results],
        use_container_width=True,
        hide_index=True,
    )

    if not_found:
        with st.expander(f"⚠ {len(not_found)} σχολεία δεν βρέθηκαν αυτόματα"):
            for n in not_found:
                st.write(f"- {n}")

    st.subheader("Διαδραστικός χάρτης")
    st.caption("Εμφανίζονται μόνο τα σχολεία της λίστας που επικόλλησες παραπάνω. Πάτα σε ένα σχολείο για δρομολόγιο από το σπίτι.")
    m = folium.Map(location=home_coords, zoom_start=12)
    folium.Marker(
        home_coords, popup="Το σπίτι μου", tooltip="Σπίτι",
        icon=folium.Icon(color="red", icon="home", prefix="fa"),
    ).add_to(m)
    for r in results:
        school_coords = (r["_lat"], r["_lon"])
        # Διακεκομμένη γραμμή σπίτι -> σχολείο (ευθεία, οπτική ένδειξη - όχι πραγματική διαδρομή)
        folium.PolyLine(
            [home_coords, school_coords],
            color="#4a90d9", weight=2, opacity=0.6, dash_array="6,6",
        ).add_to(m)

        home_lat, home_lon = home_coords
        sch_lat, sch_lon = school_coords

        # Για τα links του Google Maps προτιμάμε να στέλνουμε ΚΕΙΜΕΝΟ διεύθυνσης
        # αντί για lat/lon: το ίδιο το Google κάνει το δικό του (συνήθως πιο
        # ακριβές) geocoding, αντί να εμπιστευόμαστε τις δικές μας συντεταγμένες.
        origin_text = home_address.strip()
        if not re.search(r"ελλ[αά]δα|greece", origin_text, re.IGNORECASE):
            origin_text += ", Ελλάδα"
        origin_param = quote(origin_text)

        if r["Διεύθυνση"] and "Άγνωστη" not in r["Διεύθυνση"]:
            dest_param = quote(f"{r['Διεύθυνση']}, Ελλάδα")
        else:
            dest_param = f"{sch_lat},{sch_lon}"

        directions_driving = (
            f"https://www.google.com/maps/dir/?api=1&origin={origin_param}"
            f"&destination={dest_param}&travelmode=driving"
        )
        directions_walking = directions_driving.replace("travelmode=driving", "travelmode=walking")
        directions_transit = directions_driving.replace("travelmode=driving", "travelmode=transit")

        popup_html = f"""
        <div style="font-family: sans-serif; min-width: 220px;">
          <b>{r['Βρέθηκε ως']}</b><br>
          {r['Απόσταση (χλμ)']} χλμ από το σπίτι (ευθεία)<br>
          {r['Διεύθυνση']}<br><br>
          <a href="{directions_driving}" target="_blank">🚗 Οδηγίες (αυτοκίνητο)</a><br>
          <a href="{directions_walking}" target="_blank">🚶 Οδηγίες (περπάτημα)</a><br>
          <a href="{directions_transit}" target="_blank">🚌 Οδηγίες (Μ.Μ.Μ.)</a>
        </div>
        """
        folium.Marker(
            [r["_lat"], r["_lon"]],
            popup=folium.Popup(popup_html, max_width=280),
            tooltip=f"{r['Βρέθηκε ως']} ({r['Απόσταση (χλμ)']} χλμ) - πάτα για δρομολόγιο",
            icon=folium.Icon(color="blue", icon="graduation-cap", prefix="fa"),
        ).add_to(m)
    components.html(m._repr_html_(), height=520, scrolling=True)
else:
    st.info("Συμπλήρωσε τη διεύθυνση και τη λίστα σχολείων, μετά πάτα το κουμπί.")
